16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "bulk_signup_warning")
67	    private Boolean bulkSignupWarning;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getTelephone() {
92	        return this.telephone;
93	    }
94	
95	    public void setTelephone(String telephone) {
96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    public void setEmail(String email) {
104	        this.email = email;
105	    }
106	
107	    public String getPostcode() {
108	        return this.postcode;
109	    }
110	
111	    public void setPostcode(String postcode) {
112	        this.postcode = postcode;
113	    }
114	
115	    public LocalDate getRegistrationDate() {
116	        return this.registrationDate;
117	    }
118	
119	    public void setRegistrationDate(LocalDate registrationDate) {
120	        this.registrationDate = registrationDate;
121	    }
122	
123	    public String getCustomerCode() {
124	        return this.customerCode;
125	    }
126	
127	    public void setCustomerCode(String customerCode) {
128	        this.customerCode = customerCode;
129	    }
130	
131	    public Integer getNamesakeCount() {
132	        return this.namesakeCount;
133	    }
134	
135	    public void setNamesakeCount(Integer namesakeCount) {
136	        this.namesakeCount = namesakeCount;
137	    }
138	
139	    public Boolean getBulkSignupWarning() {
140	        return this.bulkSignupWarning;
141	    }
142	
143	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
144	        this.bulkSignupWarning = bulkSignupWarning;
145	    }
146	
147	    public Integer getHouseholdSize() {
148	        return this.householdSize;
149	    }
150	
151	    public void setHouseholdSize(Integer householdSize) {
152	        this.householdSize = householdSize;
153	    }
154	
155	    protected Set<Pet> getPetsInternal() {
156	        if (this.pets == null) {
157	            this.pets = new HashSet<>();
158	        }
159	        return this.pets;
160	    }
161	
162	    protected void setPetsInternal(Set<Pet> pets) {
163	        this.pets = pets;
164	    }
165	
166	    public List<Pet> getPets() {
167	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
168	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
169	        return Collections.unmodifiableList(sortedPets);
170	    }
171	
172	    public void setPets(List<Pet> pets) {
173	        this.pets = new HashSet<>(pets);
174	    }
175	
176	    public void addPet(Pet pet) {
177	        getPetsInternal().add(pet);
178	        pet.setOwner(this);
179	    }
180	
181	    /**
182	     * Return the Pet with the given name, or null if none found for this Owner.
183	     *
184	     * @param name to test
185	     * @return true if pet name is already in use
186	     */
187	    public Pet getPet(String name) {
188	        return getPet(name, false);
189	    }
190	
191	    /**
192	     * Return the Pet with the given name, or null if none found for this Owner.
193	     *
194	     * @param name to test
195	     * @return true if pet name is already in use
196	     */
197	    public Pet getPet(String name, boolean ignoreNew) {
198	        name = name.toLowerCase();
199	        for (Pet pet : getPetsInternal()) {
200	            if (!ignoreNew || !pet.isNew()) {
201	                String compName = pet.getName();
202	                compName = compName.toLowerCase();
203	                if (compName.equals(name)) {
204	                    return pet;
205	                }
206	            }
207	        }
208	        return null;
209	    }
210	
211	    public Pet getPet(Integer petId) {
212	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
213	    }
214	
215	    @Override
216	    public String toString() {
217	        return new ToStringCreator(this)
218	
219	            .append("id", this.getId())
220	            .append("new", this.isNew())
221	            .append("lastName", this.getLastName())
222	            .append("firstName", this.getFirstName())
223	            .append("address", this.address)
224	            .append("city", this.city)
225	            .append("telephone", this.telephone)
226	            .append("email", this.email)
227	            .toString();
228	    }
229	}
