17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
32	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.util.Households;
47	import org.springframework.samples.petclinic.util.Localities;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
67	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
68	     * numeric {@code membershipLevel}.
69	     */
70	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
121	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
122	        if (registrationDate == null) {
123	            registrationDate = java.time.LocalDate.now();
124	        }
125	        registrationDate = toBusinessDay(registrationDate);
126	        owner.setRegistrationDate(registrationDate);
127	        rejectDailyLimitReached(registrationDate);
128	        rejectCityAtCapacity(owner.getCity());
129	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
130	        owner.setTelephone(telephone);
131	        String email = normalizeEmail(ownerFieldsDto.getEmail());
132	        owner.setEmail(email);
133	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
134	        rejectDuplicateIdentity(owner);
135	        String region = Localities.region(owner.getPostcode(), owner.getCity());
136	        owner.setCustomerCode(assignCustomerCode(region, owner.getTelephone(), owner.getLastName()));
137	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
138	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
139	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
140	        this.clinicService.saveOwner(owner);
141	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
142	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
143	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
144	            ownerDto.getMembershipLevel());
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
149	
150	    /**
151	     * The maximum number of owners that may be created in a single day. Creating an owner once this
152	     * many owners already carry today's {@code registrationDate} is rejected.
153	     */
154	    private static final int DAILY_OWNER_LIMIT = 100;
155	
156	    /**
157	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
158	     * given business day as their {@code registrationDate}. The count is keyed by the
159	     * business-day-adjusted registration date of the owner being created (see
160	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
161	     * with no {@code registrationDate} are ignored.
162	     *
163	     * @param registrationDate the business-day-adjusted registration date of the owner being created
164	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
165	     */
166	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
167	        long count = this.clinicService.findAllOwners().stream()
168	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
169	            .count();
170	        if (count >= DAILY_OWNER_LIMIT) {
171	            throw new DailyOwnerLimitException(registrationDate);
172	        }
173	    }
174	
175	    /**
176	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
177	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
178	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
179	     */
180	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
181	
182	    /**
183	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
184	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
185	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
186	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
187	     * owner being created is excluded (it has not yet been saved).
188	     *
189	     * @param registrationDate the business-day-adjusted registration date of the owner being created
190	     * @return {@code true} if more than the threshold of owners already carry this business day
191	     */
192	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
193	        long count = this.clinicService.findAllOwners().stream()
194	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
195	            .count();
196	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
197	    }
198	
199	    /**
200	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
201	     * the following Monday; a weekday is returned unchanged. This applies to the effective
202	     * registration date whether it was supplied in the request or defaulted to the server date, and
203	     * every value derived from the registration date uses the adjusted result.
204	     *
205	     * @param date the effective registration date
206	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
207	     */
208	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
209	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
210	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
211	            date = date.plusDays(1);
212	        }
213	        return date;
214	    }
215	
216	    /**
217	     * The maximum number of owners a single city may contain. Creating an owner in a city that
218	     * already holds this many owners is rejected.
219	     */
220	    private static final int CITY_CAPACITY = 50;
221	
222	    /**
223	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
224	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
225	     * treated as empty).
226	     *
227	     * @param city the city of the owner being created
228	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
229	     */
230	    private void rejectCityAtCapacity(String city) {
231	        String cityValue = city == null ? "" : city;
232	        long count = this.clinicService.findAllOwners().stream()
233	            .filter(existing -> cityValue.equalsIgnoreCase(
234	                existing.getCity() == null ? "" : existing.getCity()))
235	            .count();
236	        if (count >= CITY_CAPACITY) {
237	            throw new CityAtCapacityException(city);
238	        }
239	    }
240	
241	    /**
242	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
243	     * REGION is the owner's canonical region (derived by preferring the postcode, see
244	     * {@link Localities#region(String, String)} — the same region derivation shared with the
245	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
246	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
247	     * There are no sequence numbers: the code is fully derived from the owner's own identity fields.
248	     *
249	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
250	     * @param telephone the owner's normalized (E.164) telephone
251	     * @param lastName the owner's last name
252	     * @return the assigned customer code
253	     */
254	    private String assignCustomerCode(String region, String telephone, String lastName) {
255	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
256	        String hash8 = sha256UpperHex(basis).substring(0, 8);
257	        return region + "-" + hash8;
258	    }
259	
260	    /**
261	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
262	     */
263	    private static String sha256UpperHex(String value) {
264	        try {
265	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
266	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
267	            StringBuilder sb = new StringBuilder(digest.length * 2);
268	            for (byte b : digest) {
269	                sb.append(String.format("%02X", b));
270	            }
271	            return sb.toString();
272	        }
273	        catch (java.security.NoSuchAlgorithmException e) {
274	            throw new IllegalStateException("SHA-256 not available", e);
275	        }
276	    }
277	
278	    /**
279	     * Counts how many existing owners share the given first and last name, compared
280	     * case-insensitively, at the time this owner is created. The value excludes the owner
281	     * being created (which has not yet been saved) and is stored on the new owner and returned
282	     * as its {@code namesakeCount}.
283	     *
284	     * @param firstName the first name of the owner being created
285	     * @param lastName the last name of the owner being created
286	     * @return the number of existing owners with the same first and last name
287	     */
288	    private int countNamesakes(String firstName, String lastName) {
289	        String first = firstName == null ? "" : firstName;
290	        String last = lastName == null ? "" : lastName;
291	        return (int) this.clinicService.findAllOwners().stream()
292	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
293	                && last.equalsIgnoreCase(existing.getLastName()))
294	            .count();
295	    }
296	
297	    /**
298	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
299	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
300	     * name and address). The value excludes the owner being created (which has not yet been saved), so
301	     * the household's size after this create is this count plus one. It is stored on the new owner.
302	     *
303	     * @param lastName the last name of the owner being created
304	     * @param address the normalized address of the owner being created
305	     * @return the number of existing owners sharing this owner's household
306	     */
307	    private int countHouseholdMembers(String lastName, String address) {
308	        String householdId = Households.householdId(lastName, address);
309	        return (int) this.clinicService.findAllOwners().stream()
310	            .filter(existing -> householdId.equals(
311	                Households.householdId(existing.getLastName(), existing.getAddress())))
312	            .count();
313	    }
314	
315	    /**
316	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
317	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
318	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
319	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
320	     * {@code "+61412345678"}. The E.164 value is stored and returned.
321	     * <p>
322	     * The national-number length (the digits after the country code) is additionally validated for
323	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
324	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
325	     *
326	     * @param telephone the raw telephone as submitted
327	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
328	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
329	     *         or its national-number length is wrong for its country code
330	     */
331	    private String normalizeTelephone(String telephone) {
332	        String raw = telephone == null ? "" : telephone.trim();
333	        boolean hasCountryCode = raw.startsWith("+");
334	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
335	        if (hasCountryCode) {
336	            cleaned = cleaned.substring(1);
337	        }
338	        String digits;
339	        if (hasCountryCode) {
340	            digits = cleaned;
341	        } else {
342	            if (cleaned.startsWith("0")) {
343	                cleaned = cleaned.substring(1);
344	            }
345	            digits = "61" + cleaned;
346	        }
347	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
348	            throw new InvalidTelephoneException(telephone);
349	        }
350	        return "+" + digits;
351	    }
352	
353	    /**
354	     * Checks the national-number length of an E.164 digit string against its country code for the
355	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
356	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
357	     *
358	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
359	     * @return {@code true} if the national-number length is acceptable for the country code
360	     */
361	    private boolean hasValidNationalLength(String digits) {
362	        if (digits.startsWith("61")) {
363	            return digits.length() - 2 == 9;
364	        }
365	        if (digits.startsWith("1")) {
366	            return digits.length() - 1 == 10;
367	        }
368	        return true;
369	    }
370	
371	    /**
372	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
373	     * multi-character top-level label. Deliberately lenient about the exact character set while still
374	     * rejecting values that are clearly not addresses (e.g. missing '@').
375	     */
376	    private static final java.util.regex.Pattern EMAIL_PATTERN =
377	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
378	
379	    /**
380	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
381	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
382	     * lower-cased before being stored and returned.
383	     *
384	     * @param email the raw email as submitted, may be {@code null}
385	     * @return the lower-cased email, or {@code null} when none was supplied
386	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
387	     */
388	    private String normalizeEmail(String email) {
389	        if (email == null || email.isBlank()) {
390	            return null;
391	        }
392	        String trimmed = email.trim();
393	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
394	            throw new InvalidEmailException(email);
395	        }
396	        return trimmed.toLowerCase(java.util.Locale.ROOT);
397	    }
398	
399	    /**
400	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
401	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
402	     * {@link Localities#region}) accepts any 4-digit postcode.
403	     */
404	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
405	        "NSW", new int[] {2000, 2099},
406	        "VIC", new int[] {3000, 3099},
407	        "QLD", new int[] {4000, 4099});
408	
409	    /**
410	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
411	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
412	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
413	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
414	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
415	     *
416	     * @param city the owner's city, used to derive the region whose range constrains the postcode
417	     * @param postcode the raw postcode as submitted, may be {@code null}
418	     * @return the postcode when supplied, or {@code null} when none was supplied
419	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
420	     *         out of range for the city's region
421	     */
422	    private String validatePostcode(String city, String postcode) {
423	        if (postcode == null || postcode.isBlank()) {
424	            return null;
425	        }
426	        if (!postcode.matches("[0-9]{4}")) {
427	            throw new InvalidPostcodeException(postcode);
428	        }
429	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
430	        if (range != null) {
431	            int value = Integer.parseInt(postcode);
432	            if (value < range[0] || value > range[1]) {
433	                throw new InvalidPostcodeException(postcode);
434	            }
435	        }
436	        return postcode;
437	    }
438	
439	    /**
440	     * Common street-type abbreviations expanded to their full word during address normalization.
441	     */
442	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
443	        "ST", "STREET",
444	        "RD", "ROAD",
445	        "AVE", "AVENUE");
446	
447	    /**
448	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
449	     * whitespace collapse to a single space, the value is upper-cased and common street-type
450	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
451	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
452	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
453	     * for every address comparison (household duplicate detection and the shared household id).
454	     *
455	     * @param address the raw address as submitted
456	     * @return the normalized address
457	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
458	     */
459	    private String normalizeAddress(String address) {
460	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
461	        if (collapsed.isEmpty()) {
462	            throw new InvalidAddressException(address);
463	        }
464	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
465	        StringBuilder normalized = new StringBuilder(collapsed.length());
466	        for (int i = 0; i < tokens.length; i++) {
467	            if (i > 0) {
468	                normalized.append(' ');
469	            }
470	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
471	        }
472	        return normalized.toString();
473	    }
474	
475	    /**
476	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
477	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
478	     * owners are duplicates when they share the same normalized telephone and the same normalized email
479	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
480	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
481	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
482	     * still match.
483	     * <p>
484	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
485	     * grouping, so two members of the same household with different telephones have different
486	     * identities and are both allowed. Only owners with the same telephone and email collide.
487	     *
488	     * @param owner the owner being created, with its telephone and email already normalized
489	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
490	     */
491	    private void rejectDuplicateIdentity(Owner owner) {
492	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
493	        boolean duplicate = this.clinicService.findAllOwners().stream()
494	            .anyMatch(existing -> identity.equals(
495	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
496	        if (duplicate) {
497	            String householdId = Households.householdId(owner.getLastName(), owner.getAddress());
498	            throw new DuplicateIdentityException(
499	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
500	        }
501	    }
502	
503	    /**
504	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
505	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
506	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
507	     */
508	    private String personalIdentity(String telephone, String email) {
509	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
510	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
511	    }
512	
513	    /**
514	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
515	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
516	     * when its national-number length does not match its country code.
517	     */
518	    private String toE164OrNull(String telephone) {
519	        try {
520	            return normalizeTelephone(telephone);
521	        } catch (InvalidTelephoneException e) {
522	            return null;
523	        }
524	    }
525	
526	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
527	    @Override
528	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
529	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
530	        if (currentOwner == null) {
531	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
532	        }
533	        currentOwner.setAddress(ownerFieldsDto.getAddress());
534	        currentOwner.setCity(ownerFieldsDto.getCity());
535	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
536	        currentOwner.setLastName(ownerFieldsDto.getLastName());
537	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
538	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
539	        this.clinicService.saveOwner(currentOwner);
540	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
541	    }
542	
543	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
544	    @Transactional
545	    @Override
546	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
547	        Owner owner = this.clinicService.findOwnerById(ownerId);
548	        if (owner == null) {
549	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
550	        }
551	        this.clinicService.deleteOwner(owner);
552	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
553	    }
554	
555	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
556	    @Override
557	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
558	        Owner owner = this.clinicService.findOwnerById(ownerId);
559	        if (owner == null) {
560	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
561	        }
562	        HttpHeaders headers = new HttpHeaders();
563	        Pet pet = petMapper.toPet(petFieldsDto);
564	        owner.setId(ownerId);
565	        pet.setOwner(owner);
566	        pet.getType().setName(null);
567	        this.clinicService.savePet(pet);
568	        PetDto petDto = petMapper.toPetDto(pet);
569	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
570	            .buildAndExpand(pet.getId()).toUri());
571	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
572	    }
573	
574	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
575	    @Override
576	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
577	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
578	        if (currentOwner != null) {
579	            Pet currentPet = this.clinicService.findPetById(petId);
580	            if (currentPet != null) {
581	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
582	                currentPet.setName(petFieldsDto.getName());
583	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
584	                this.clinicService.savePet(currentPet);
585	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
586	            }
587	        }
588	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
589	    }
590	
591	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
592	    @Override
593	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
594	        HttpHeaders headers = new HttpHeaders();
595	        Visit visit = visitMapper.toVisit(visitFieldsDto);
596	        Pet pet = new Pet();
597	        pet.setId(petId);
598	        visit.setPet(pet);
599	        this.clinicService.saveVisit(visit);
600	        VisitDto visitDto = visitMapper.toVisitDto(visit);
601	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
602	            .buildAndExpand(visit.getId()).toUri());
603	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
604	    }
605	
606	
607	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
608	    @Override
609	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
610	        Owner owner = this.clinicService.findOwnerById(ownerId);
611	        if (owner != null) {
612	            Pet pet = owner.getPet(petId);
613	            if (pet != null) {
614	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
615	            }
616	        }
617	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
618	    }
619	}
