356	     * @param request {@link HttpServletRequest} object referring to the current request.
357	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
358	     */
359	    @ExceptionHandler(MethodArgumentNotValidException.class)
360	    @ResponseBody
361	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
362	        HttpStatus status = HttpStatus.BAD_REQUEST;
363	        BindingErrorsResponse errors = new BindingErrorsResponse();
364	        BindingResult bindingResult = e.getBindingResult();
365	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
366	        if (bindingResult.hasErrors()) {
367	            errors.addAllErrors(bindingResult);
368	            List<String> errorFields = bindingResult.getFieldErrors().stream()
369	                .map(org.springframework.validation.FieldError::getField)
370	                .distinct()
371	                .toList();
372	            detail.setProperty("errors", errorFields);
373	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
374	                .map(fieldError -> {
375	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
376	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
377	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
378	                        fieldError.getField(),
379	                        defaultMessage,
380	                        rejectedValue);
381	                    return new ValidationMessageDto(message)
382	                        .putAdditionalProperty("field", fieldError.getField())
383	                        .putAdditionalProperty("rejectedValue", rejectedValue)
384	                        .putAdditionalProperty("defaultMessage", defaultMessage);
385	                })
386	                .toList();
387	            logger.debug("Validation error at {} {}: {}",
388	                request.getMethod(),
389	                request.getRequestURI(),
390	                bindingResult.getFieldErrors());
391	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
392	            return ResponseEntity.status(status).body(detail);
393	        }
394	        return ResponseEntity.status(status).body(detail);
395	    }
