        detail.setProperty("errors", List.of("postcode"));
        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
        detail.setProperty("schemaValidationErrors", List.of(
            new ValidationMessageDto("Field 'postcode' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
                .putAdditionalProperty("field", "postcode")
                .putAdditionalProperty("rejectedValue", rejectedValue)
                .putAdditionalProperty("defaultMessage", e.getMessage())));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link InvalidAddressException} thrown while normalizing an owner's address on create.
     *
     * @param e The {@link InvalidAddressException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
     */
    @ExceptionHandler(InvalidAddressException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleInvalidAddressException(InvalidAddressException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.BAD_REQUEST;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
        detail.setProperty("errors", List.of("address"));
        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
        detail.setProperty("schemaValidationErrors", List.of(
            new ValidationMessageDto("Field 'address' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
                .putAdditionalProperty("field", "address")
                .putAdditionalProperty("rejectedValue", rejectedValue)
                .putAdditionalProperty("defaultMessage", e.getMessage())));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link DuplicateTelephoneException} thrown when creating an owner whose normalized
     * telephone is already used by another owner.
     *
     * @param e The {@link DuplicateTelephoneException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
     */
    @ExceptionHandler(DuplicateTelephoneException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.CONFLICT;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
        detail.setProperty("errors", List.of("telephone"));
        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
        detail.setProperty("schemaValidationErrors", List.of(
            new ValidationMessageDto("Field 'telephone' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
                .putAdditionalProperty("field", "telephone")
                .putAdditionalProperty("rejectedValue", rejectedValue)
                .putAdditionalProperty("defaultMessage", e.getMessage())));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link DuplicateEmailException} thrown when creating an owner whose lower-cased email is
     * already used by another owner.
     *
     * @param e The {@link DuplicateEmailException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
     */
    @ExceptionHandler(DuplicateEmailException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleDuplicateEmailException(DuplicateEmailException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.CONFLICT;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
        detail.setProperty("errors", List.of("email"));
        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
        detail.setProperty("schemaValidationErrors", List.of(
            new ValidationMessageDto("Field 'email' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
                .putAdditionalProperty("field", "email")
                .putAdditionalProperty("rejectedValue", rejectedValue)
                .putAdditionalProperty("defaultMessage", e.getMessage())));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link DuplicateHouseholdException} thrown when creating an owner whose last name and
     * address already match another owner (they share a household) without opting in via
     * {@code sharesHousehold}.
     *
     * @param e The {@link DuplicateHouseholdException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
     */
    @ExceptionHandler(DuplicateHouseholdException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.CONFLICT;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
        detail.setProperty("errors", List.of("lastName", "address"));
        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
        detail.setProperty("schemaValidationErrors", List.of(
            new ValidationMessageDto("Fields 'lastName' and 'address' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
                .putAdditionalProperty("field", "lastName")
                .putAdditionalProperty("rejectedValue", rejectedValue)
                .putAdditionalProperty("defaultMessage", e.getMessage())));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link DuplicateIdentityException} thrown when creating an owner whose derived
     * {@code identityKey} is already used by another owner.
     *
     * @param e The {@link DuplicateIdentityException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
     */
    @ExceptionHandler(DuplicateIdentityException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.CONFLICT;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
        detail.setProperty("errors", List.of("identityKey"));
        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
        detail.setProperty("schemaValidationErrors", List.of(
            new ValidationMessageDto("Field 'identityKey' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
                .putAdditionalProperty("field", "identityKey")
                .putAdditionalProperty("rejectedValue", rejectedValue)
                .putAdditionalProperty("defaultMessage", e.getMessage())));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link CityAtCapacityException} thrown when creating an owner whose city already
     * contains the maximum number of owners.
     *
     * @param e The {@link CityAtCapacityException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
     */
    @ExceptionHandler(CityAtCapacityException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.CONFLICT;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
        detail.setProperty("errors", List.of("city"));
        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
        detail.setProperty("schemaValidationErrors", List.of(
            new ValidationMessageDto("Field 'city' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
                .putAdditionalProperty("field", "city")
                .putAdditionalProperty("rejectedValue", rejectedValue)
                .putAdditionalProperty("defaultMessage", e.getMessage())));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link DailyOwnerLimitException} thrown when creating an owner after the daily limit of
     * owner registrations has already been reached.
     *
     * @param e The {@link DailyOwnerLimitException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
     */
    @ExceptionHandler(DailyOwnerLimitException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
        detail.setProperty("errors", List.of("registrationDate"));
        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
        detail.setProperty("schemaValidationErrors", List.of(
            new ValidationMessageDto("Field 'registrationDate' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
                .putAdditionalProperty("field", "registrationDate")
                .putAdditionalProperty("rejectedValue", rejectedValue)
                .putAdditionalProperty("defaultMessage", e.getMessage())));
        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles exception thrown by Bean Validation on controller methods parameters
     *
     * @param e The {@link MethodArgumentNotValidException} to be handled
     * @param request {@link HttpServletRequest} object referring to the current request.
     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseBody
    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
        HttpStatus status = HttpStatus.BAD_REQUEST;
        BindingErrorsResponse errors = new BindingErrorsResponse();
        BindingResult bindingResult = e.getBindingResult();
        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
        if (bindingResult.hasErrors()) {
            errors.addAllErrors(bindingResult);
            List<String> errorFields = bindingResult.getFieldErrors().stream()
                .map(org.springframework.validation.FieldError::getField)
                .distinct()
                .toList();
            detail.setProperty("errors", errorFields);
            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
                .map(fieldError -> {
                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
                    String message = "Field '%s' %s (rejected value: %s)".formatted(
                        fieldError.getField(),
                        defaultMessage,
                        rejectedValue);
                    return new ValidationMessageDto(message)
                        .putAdditionalProperty("field", fieldError.getField())
                        .putAdditionalProperty("rejectedValue", rejectedValue)
                        .putAdditionalProperty("defaultMessage", defaultMessage);
                })
                .toList();
            logger.debug("Validation error at {} {}: {}",
                request.getMethod(),
                request.getRequestURI(),
                bindingResult.getFieldErrors());
            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
            return ResponseEntity.status(status).body(detail);
        }
        return ResponseEntity.status(status).body(detail);
    }

}

